46	import jadx.core.utils.exceptions.JadxRuntimeException;
47	
48	public class SimplifyVisitor extends AbstractVisitor {
49	
50		private static final Logger LOG = LoggerFactory.getLogger(SimplifyVisitor.class);
51	
52		private MethodInfo stringGetBytesMth;
53	
54		@Override
55		public void init(RootNode root) {
56			stringGetBytesMth = MethodInfo.fromDetails(
57					root,
58					ClassInfo.fromType(root, ArgType.STRING),
59					"getBytes",
60					Collections.emptyList(),
61					ArgType.array(ArgType.BYTE));
62		}
63	
64		@Override
65		public void visit(MethodNode mth) {
66			if (mth.isNoCode()) {
67				return;
68			}
69			boolean changed = false;
70			for (BlockNode block : mth.getBasicBlocks()) {
71				if (simplifyBlock(mth, block)) {
72					changed = true;
73				}
74			}
75			if (changed || mth.contains(AFlag.REQUEST_CODE_SHRINK)) {
76				CodeShrinkVisitor.shrinkMethod(mth);
77			}
78		}
79	
80		private boolean simplifyBlock(MethodNode mth, BlockNode block) {
81			boolean changed = false;
82			List<InsnNode> list = block.getInstructions();
83			for (int i = 0; i < list.size(); i++) {
84				InsnNode insn = list.get(i);
85				int insnCount = list.size();
86				InsnNode modInsn = simplifyInsn(mth, insn, null);
87				if (modInsn != null) {
88					if (i < list.size() && list.get(i) == insn) {
89						list.set(i, modInsn);
90					} else {
91						int idx = InsnList.getIndex(list, insn);
92						if (idx == -1) {
93							throw new JadxRuntimeException("Failed to replace insn");
94						}
95						list.set(idx, modInsn);
96					}
97					InsnRemover.unbindInsn(mth, insn);
98					modInsn.rebindArgs();
99					if (list.size() < insnCount) {
100						// some insns removed => restart block processing
101						simplifyBlock(mth, block);
102						return true;
103					}
104					changed = true;
105				}
106			}
107			return changed;
108		}
109	
110		private void simplifyArgs(MethodNode mth, InsnNode insn) {
111			boolean changed = false;
112			for (InsnArg arg : insn.getArguments()) {
113				if (arg.isInsnWrap()) {
114					InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
115					InsnNode replaceInsn = simplifyInsn(mth, wrapInsn, insn);
116					if (replaceInsn != null) {
117						arg.wrapInstruction(mth, replaceInsn);
118						changed = true;
119					}
120				}
121			}
122			if (changed) {
123				insn.rebindArgs();
124				mth.add(AFlag.REQUEST_CODE_SHRINK);
125			}
126		}
127	
128		private InsnNode simplifyInsn(MethodNode mth, InsnNode insn, @Nullable InsnNode parentInsn) {
129			if (insn.contains(AFlag.DONT_GENERATE)) {
130				return null;
131			}
132			simplifyArgs(mth, insn);
133			switch (insn.getType()) {
134				case ARITH:
135					return simplifyArith((ArithNode) insn);
136	
137				case IF:
138					simplifyIf(mth, (IfNode) insn);
139					break;
140				case TERNARY:
141					simplifyTernary(mth, (TernaryInsn) insn);
142					break;
143	
144				case INVOKE:
145					return convertInvoke(mth, (InvokeNode) insn);
146	
147				case IPUT:
148				case SPUT:
149					return convertFieldArith(mth, insn);
150	
151				case CAST:
152				case CHECK_CAST:
153					return processCast(mth, (IndexInsnNode) insn, parentInsn);
154	
155				case MOVE:
156					InsnArg firstArg = insn.getArg(0);
157					if (firstArg.isLiteral()) {
158						InsnNode constInsn = new InsnNode(InsnType.CONST, 1);
159						constInsn.setResult(insn.getResult());
160						constInsn.addArg(firstArg);
161						constInsn.copyAttributesFrom(insn);
162						return constInsn;
163					}
164					break;
165	
166				case CONSTRUCTOR:
167					return simplifyStringConstructor(mth, (ConstructorInsn) insn);
168	
169				default:
170					break;
171			}
172			return null;
173		}
174	
175		private InsnNode simplifyStringConstructor(MethodNode mth, ConstructorInsn insn) {
176			if (insn.getCallMth().getDeclClass().getType().equals(ArgType.STRING)
177					&& insn.getArgsCount() != 0
178					&& insn.getArg(0).isInsnWrap()) {
179				InsnNode arrInsn = ((InsnWrapArg) insn.getArg(0)).getWrapInsn();
180				if (arrInsn.getType() == InsnType.FILLED_NEW_ARRAY
181						&& arrInsn.getArgsCount() != 0) {
182					ArgType elemType = ((FilledNewArrayNode) arrInsn).getElemType();
183					if (elemType == ArgType.BYTE || elemType == ArgType.CHAR) {
184						int printable = 0;
185						byte[] arr = new byte[arrInsn.getArgsCount()];
186						for (int i = 0; i < arr.length; i++) {
187							InsnArg arrArg = arrInsn.getArg(i);
188							if (!arrArg.isLiteral()) {
189								return null;
190							}
191							arr[i] = (byte) ((LiteralArg) arrArg).getLiteral();
192							if (NameMapper.isPrintableChar((char) arr[i])) {
193								printable++;
194							}
195						}
196						if (printable >= arr.length - printable) {
197							InsnNode constStr = new ConstStringNode(new String(arr));
198							if (insn.getArgsCount() == 1) {
199								constStr.setResult(insn.getResult());
200								constStr.copyAttributesFrom(insn);
201								InsnRemover.unbindArgUsage(mth, insn.getArg(0));
202								return constStr;
203							} else {
204								InvokeNode in = new InvokeNode(stringGetBytesMth, InvokeType.VIRTUAL, 1);
205								in.addArg(InsnArg.wrapArg(constStr));
206								InsnArg bytesArg = InsnArg.wrapArg(in);
207								bytesArg.setType(stringGetBytesMth.getReturnType());
208								insn.setArg(0, bytesArg);
209								return null;
210							}
211						}
212					}
213				}
214			}
215			return null;
216		}
