218		private static InsnNode processCast(MethodNode mth, IndexInsnNode castInsn, @Nullable InsnNode parentInsn) {
219			if (castInsn.contains(AFlag.EXPLICIT_CAST)) {
220				return null;
221			}
222			InsnArg castArg = castInsn.getArg(0);
223			ArgType argType = castArg.getType();
224	
225			// Don't removes CHECK_CAST for wrapped INVOKE if invoked method returns different type
226			if (castArg.isInsnWrap()) {
227				InsnNode wrapInsn = ((InsnWrapArg) castArg).getWrapInsn();
228				if (wrapInsn.getType() == InsnType.INVOKE) {
229					argType = ((InvokeNode) wrapInsn).getCallMth().getReturnType();
230				}
231			}
232	
233			ArgType castToType = (ArgType) castInsn.getIndex();
234			if (isArithWideUpCast(parentInsn, argType, castToType)) {
235				return null;
236			}
237			if (!ArgType.isCastNeeded(mth.root(), argType, castToType)
238					|| isCastDuplicate(castInsn)
239					|| shadowedByOuterCast(mth.root(), castToType, parentInsn)) {
240				InsnNode insnNode = new InsnNode(InsnType.MOVE, 1);
241				insnNode.setOffset(castInsn.getOffset());
242				insnNode.setResult(InsnNode.duplicateArg(castInsn.getResult()));
243				insnNode.addArg(castArg.duplicate());
244				return insnNode;
245			}
246			return null;
247		}
248	
249		/**
250		 * Keep cast to wide types in arith instructions,
251		 * because arguments type determine instruction used in result bytecode.
252		 * Example: (long) i << 32 - without 'long' cast will be used 'int shift' instruction and result
253		 * will be incorrect
254		 */
255		private static boolean isArithWideUpCast(@Nullable InsnNode parentInsn, ArgType argType, ArgType castToType) {
256			if (parentInsn != null
257					&& parentInsn.getType() == InsnType.ARITH
258					&& argType.isPrimitive() && castToType.isPrimitive()) {
259				return castToType.getRegCount() > argType.getRegCount();
260			}
261			return false;
262		}
263	
264		private static boolean isCastDuplicate(IndexInsnNode castInsn) {
265			InsnArg arg = castInsn.getArg(0);
266			if (arg.isRegister()) {
267				SSAVar sVar = ((RegisterArg) arg).getSVar();
268				if (sVar != null && sVar.getUseCount() == 1 && !sVar.isUsedInPhi()) {
269					InsnNode assignInsn = sVar.getAssign().getParentInsn();
270					if (assignInsn != null && assignInsn.getType() == InsnType.CHECK_CAST) {
271						ArgType assignCastType = (ArgType) ((IndexInsnNode) assignInsn).getIndex();
272						return assignCastType.equals(castInsn.getIndex());
273					}
274				}
275			}
276			return false;
277		}
278	
279		private static boolean shadowedByOuterCast(RootNode root, ArgType castType, @Nullable InsnNode parentInsn) {
280			if (parentInsn != null && parentInsn.getType() == InsnType.CAST) {
281				ArgType parentCastType = (ArgType) ((IndexInsnNode) parentInsn).getIndex();
282				TypeCompareEnum result = root.getTypeCompare().compareTypes(parentCastType, castType);
283				return result.isNarrow();
284			}
285			return false;
286		}
287	
288		/**
289		 * Simplify 'cmp' instruction in if condition
290		 */
291		private static void simplifyIf(MethodNode mth, IfNode insn) {
292			InsnArg f = insn.getArg(0);
293			if (f.isInsnWrap()) {
294				InsnNode wi = ((InsnWrapArg) f).getWrapInsn();
295				if (wi.getType() == InsnType.CMP_L || wi.getType() == InsnType.CMP_G) {
296					if (insn.getArg(1).isZeroLiteral()) {
297						insn.changeCondition(insn.getOp(), wi.getArg(0).duplicate(), wi.getArg(1).duplicate());
298						InsnRemover.unbindInsn(mth, wi);
299					} else {
300						LOG.warn("TODO: cmp {}", insn);
301					}
302				}
303			}
304		}
305	
306		/**
307		 * Simplify condition in ternary operation
308		 */
309		private static void simplifyTernary(MethodNode mth, TernaryInsn insn) {
310			IfCondition condition = insn.getCondition();
311			if (condition.isCompare()) {
312				simplifyIf(mth, condition.getCompare().getInsn());
313			} else {
314				insn.simplifyCondition();
315			}
316		}
317	
318		/**
319		 * Simplify chains of calls to StringBuilder#append() plus constructor of StringBuilder.
320		 * Those chains are usually automatically generated by the Java compiler when you create String
321		 * concatenations like <code>"text " + 1 + " text"</code>.
322		 */
323		private static InsnNode convertInvoke(MethodNode mth, InvokeNode insn) {
324			MethodInfo callMth = insn.getCallMth();
325	
326			if (callMth.getDeclClass().getFullName().equals(Consts.CLASS_STRING_BUILDER)
327					&& callMth.getShortId().equals(Consts.MTH_TOSTRING_SIGNATURE)) {
328				InsnArg instanceArg = insn.getArg(0);
329				if (instanceArg.isInsnWrap()) {
330					// Convert 'new StringBuilder(xxx).append(yyy).append(zzz).toString() to STRING_CONCAT insn
331					List<InsnNode> callChain = flattenInsnChainUntil(insn, InsnType.CONSTRUCTOR);
332					return convertStringBuilderChain(mth, insn, callChain);
333				}
334				if (instanceArg.isRegister()) {
335					// Convert 'StringBuilder sb = new StringBuilder(xxx); sb.append(yyy); String str = sb.toString();'
336					List<InsnNode> useChain = collectUseChain(mth, insn, (RegisterArg) instanceArg);
337					return convertStringBuilderChain(mth, insn, useChain);
338				}
339			}
340			return null;
341		}
342	
343		private static List<InsnNode> collectUseChain(MethodNode mth, InvokeNode insn, RegisterArg instanceArg) {
344			SSAVar sVar = instanceArg.getSVar();
345			if (sVar.isUsedInPhi() || sVar.getUseCount() == 0) {
346				return Collections.emptyList();
347			}
348			List<InsnNode> useChain = new ArrayList<>(sVar.getUseCount() + 1);
349			InsnNode assignInsn = sVar.getAssign().getParentInsn();
350			if (assignInsn == null) {
351				return Collections.emptyList();
352			}
353			useChain.add(assignInsn);
354			for (RegisterArg reg : sVar.getUseList()) {
355				InsnNode parentInsn = reg.getParentInsn();
356				if (parentInsn == null) {
357					return Collections.emptyList();
358				}
359				useChain.add(parentInsn);
360			}
361			int toStrIdx = InsnList.getIndex(useChain, insn);
362			if (useChain.size() - 1 != toStrIdx) {
363				return Collections.emptyList();
364			}
365			useChain.remove(toStrIdx);
366	
367			// all insns must be in one block and sequential
368			BlockNode assignBlock = BlockUtils.getBlockByInsn(mth, assignInsn);
369			if (assignBlock == null) {
370				return Collections.emptyList();
371			}
372			List<InsnNode> blockInsns = assignBlock.getInstructions();
373			int assignIdx = InsnList.getIndex(blockInsns, assignInsn);
374			int chainSize = useChain.size();
375			int lastInsn = blockInsns.size() - assignIdx;
376			if (lastInsn < chainSize) {
377				return Collections.emptyList();
378			}
379			for (int i = 1; i < chainSize; i++) {
380				if (blockInsns.get(assignIdx + i) != useChain.get(i)) {
381					return Collections.emptyList();
382				}
383			}
384			return useChain;
385		}
386	
387		private static InsnNode convertStringBuilderChain(MethodNode mth, InvokeNode toStrInsn, List<InsnNode> chain) {
388			try {
389				int chainSize = chain.size();
390				if (chainSize < 2) {
391					return null;
392				}
393				List<InsnArg> args = new ArrayList<>(chainSize);
394				InsnNode firstInsn = chain.get(0);
395				if (firstInsn.getType() != InsnType.CONSTRUCTOR) {
396					return null;
397				}
398				ConstructorInsn constrInsn = (ConstructorInsn) firstInsn;
399				if (constrInsn.getArgsCount() == 1) {
400					ArgType argType = constrInsn.getCallMth().getArgumentsTypes().get(0);
401					if (!argType.isObject()) {
402						return null;
403					}
404					args.add(constrInsn.getArg(0));
405				}
406				for (int i = 1; i < chainSize; i++) {
407					InsnNode chainInsn = chain.get(i);
408					InsnArg arg = getArgFromAppend(chainInsn);
409					if (arg == null) {
410						return null;
411					}
412					args.add(arg);
413				}
414	
415				// all check passed
416				List<InsnArg> dupArgs = Utils.collectionMap(args, InsnArg::duplicate);
417				List<InsnArg> simplifiedArgs = concatConstArgs(dupArgs);
418				InsnNode concatInsn = new InsnNode(InsnType.STR_CONCAT, simplifiedArgs);
419				concatInsn.add(AFlag.SYNTHETIC);
420				if (toStrInsn.getResult() == null && !toStrInsn.contains(AFlag.WRAPPED)) {
421					// string concat without assign to variable will cause compilation error
422					concatInsn.setResult(mth.makeSyntheticRegArg(ArgType.STRING));
423				} else {
424					concatInsn.setResult(toStrInsn.getResult());
425				}
426				concatInsn.copyAttributesFrom(toStrInsn);
427				removeStringBuilderInsns(mth, toStrInsn, chain);
428				return concatInsn;
429			} catch (Exception e) {
430				mth.addWarnComment("String concatenation convert failed", e);
431			}
432			return null;
433		}
434	
435		private static boolean isConstConcatNeeded(List<InsnArg> args) {
436			boolean prevConst = false;
437			for (InsnArg arg : args) {
438				boolean curConst = arg.isConst();
439				if (curConst && prevConst) {
440					// found 2 consecutive constants
441					return true;
442				}
443				prevConst = curConst;
444			}
445			return false;
446		}
447	
448		private static List<InsnArg> concatConstArgs(List<InsnArg> args) {
449			if (!isConstConcatNeeded(args)) {
450				return args;
451			}
452			int size = args.size();
453			List<InsnArg> newArgs = new ArrayList<>(size);
454			List<String> concatList = new ArrayList<>(size);
455			for (int i = 0; i < size; i++) {
456				InsnArg arg = args.get(i);
457				String constStr = getConstString(arg);
458				if (constStr != null) {
459					concatList.add(constStr);
460				} else {
461					if (!concatList.isEmpty()) {
462						newArgs.add(getConcatArg(concatList, args, i));
463						concatList.clear();
464					}
465					newArgs.add(arg);
466				}
467			}
468			if (!concatList.isEmpty()) {
469				newArgs.add(getConcatArg(concatList, args, size));
470			}
471			return newArgs;
472		}
473	
474		private static InsnArg getConcatArg(List<String> concatList, List<InsnArg> args, int idx) {
475			if (concatList.size() == 1) {
476				return args.get(idx - 1);
477			}
478			String str = Utils.concatStrings(concatList);
479			return InsnArg.wrapArg(new ConstStringNode(str));
480		}
481	
482		@Nullable
483		private static String getConstString(InsnArg arg) {
484			if (arg.isLiteral()) {
485				return TypeGen.literalToRawString((LiteralArg) arg);
486			}
487			if (arg.isInsnWrap()) {
488				InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
489				if (wrapInsn instanceof ConstStringNode) {
490					return ((ConstStringNode) wrapInsn).getString();
491				}
492			}
493			return null;
494		}
495	
496		/**
497		 * Remove and unbind all instructions with StringBuilder
498		 */
499		private static void removeStringBuilderInsns(MethodNode mth, InvokeNode toStrInsn, List<InsnNode> chain) {
500			InsnRemover.unbindAllArgs(mth, toStrInsn);
501			for (InsnNode insnNode : chain) {
502				InsnRemover.unbindAllArgs(mth, insnNode);
503			}
504			InsnRemover insnRemover = new InsnRemover(mth);
505			for (InsnNode insnNode : chain) {
506				if (insnNode != toStrInsn) {
507					insnRemover.addAndUnbind(insnNode);
508				}
509			}
510			insnRemover.perform();
511		}
512	
513		private static List<InsnNode> flattenInsnChainUntil(InsnNode insn, InsnType insnType) {
514			List<InsnNode> chain = new ArrayList<>();
515			InsnArg arg = insn.getArg(0);
516			while (arg.isInsnWrap()) {
517				InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
518				chain.add(wrapInsn);
519				if (wrapInsn.getType() == insnType
520						|| wrapInsn.getArgsCount() == 0) {
521					break;
522				}
523				arg = wrapInsn.getArg(0);
524			}
525			Collections.reverse(chain);
526			return chain;
527		}
528	
529		private static InsnArg getArgFromAppend(InsnNode chainInsn) {
530			if (chainInsn.getType() == InsnType.INVOKE && chainInsn.getArgsCount() == 2) {
531				MethodInfo callMth = ((InvokeNode) chainInsn).getCallMth();
532				if (callMth.getDeclClass().getFullName().equals(Consts.CLASS_STRING_BUILDER)
533						&& callMth.getName().equals("append")) {
534					return chainInsn.getArg(1);
535				}
536			}
537			return null;
538		}
539	
540		private static InsnNode simplifyArith(ArithNode arith) {
541			if (arith.getArgsCount() != 2) {
542				return null;
543			}
544			LiteralArg litArg = null;
545			InsnArg secondArg = arith.getArg(1);
546			if (secondArg.isInsnWrap()) {
547				InsnNode wr = ((InsnWrapArg) secondArg).getWrapInsn();
548				if (wr.getType() == InsnType.CONST) {
549					InsnArg arg = wr.getArg(0);
550					if (arg.isLiteral()) {
551						litArg = (LiteralArg) arg;
552					}
553				}
554			} else if (secondArg.isLiteral()) {
555				litArg = (LiteralArg) secondArg;
556			}
557			if (litArg == null) {
558				return null;
559			}
560			switch (arith.getOp()) {
561				case ADD:
562					// fix 'c + (-1)' to 'c - (1)'
563					if (litArg.isNegative()) {
564						LiteralArg negLitArg = litArg.negate();
565						if (negLitArg != null) {
566							RegisterArg resArg = InsnNode.duplicateArg(arith.getResult());
567							ArithNode newInsn = new ArithNode(ArithOp.SUB, resArg, arith.getArg(0).duplicate(), negLitArg);
568							newInsn.copyAttributesFrom(arith);
569							newInsn.setOffset(arith.getOffset());
570							return newInsn;
571						}
572					}
573					break;
574	
575				case XOR:
576					// simplify xor on boolean
577					InsnArg firstArg = arith.getArg(0);
578					long lit = litArg.getLiteral();
579					if (firstArg.getType() == ArgType.BOOLEAN && (lit == 0 || lit == 1)) {
580						InsnNode newInsn = new InsnNode(lit == 0 ? InsnType.MOVE : InsnType.NOT, 1);
581						newInsn.setResult(InsnNode.duplicateArg(arith.getResult()));
582						newInsn.addArg(firstArg.duplicate());
583						newInsn.copyAttributesFrom(arith);
584						newInsn.setOffset(arith.getOffset());
585						return newInsn;
586					}
587					break;
588			}
589			return null;
590		}
591	
592		/**
593		 * Convert field arith operation to arith instruction
594		 * (IPUT (ARITH (IGET, lit)) -> ARITH ((IGET)) <op>= lit))
595		 */
596		private static ArithNode convertFieldArith(MethodNode mth, InsnNode insn) {
597			InsnArg arg = insn.getArg(0);
598			if (!arg.isInsnWrap()) {
599				return null;
600			}
601			InsnNode wrap = ((InsnWrapArg) arg).getWrapInsn();
602			InsnType wrapType = wrap.getType();
603			if (wrapType != InsnType.ARITH && wrapType != InsnType.STR_CONCAT
604					|| !wrap.getArg(0).isInsnWrap()) {
605				return null;
606			}
607			InsnArg getWrap = wrap.getArg(0);
608			InsnNode get = ((InsnWrapArg) getWrap).getWrapInsn();
609			InsnType getType = get.getType();
610			if (getType != InsnType.IGET && getType != InsnType.SGET) {
611				return null;
612			}
613			FieldInfo field = (FieldInfo) ((IndexInsnNode) insn).getIndex();
614			FieldInfo innerField = (FieldInfo) ((IndexInsnNode) get).getIndex();
615			if (!field.equals(innerField)) {
616				return null;
617			}
618			try {
619				if (getType == InsnType.IGET && insn.getType() == InsnType.IPUT) {
620					InsnArg reg = get.getArg(0);
621					InsnArg putReg = insn.getArg(1);
622					if (!reg.equals(putReg)) {
623						return null;
624					}
625				}
626				InsnArg fArg = getWrap.duplicate();
627				InsnRemover.unbindInsn(mth, get);
628				if (insn.getType() == InsnType.IPUT) {
629					InsnRemover.unbindArgUsage(mth, insn.getArg(1));
630				}
631				if (wrapType == InsnType.ARITH) {
632					ArithNode ar = (ArithNode) wrap;
633					ArithNode newInsn = ArithNode.oneArgOp(ar.getOp(), fArg, ar.getArg(1).duplicate());
634					newInsn.copyAttributesFrom(insn);
635					newInsn.setOffset(insn.getOffset());
636					return newInsn;
637				}
638				int argsCount = wrap.getArgsCount();
639				InsnNode concat = new InsnNode(InsnType.STR_CONCAT, argsCount - 1);
640				for (int i = 1; i < argsCount; i++) {
641					concat.addArg(wrap.getArg(i).duplicate());
642				}
643				InsnArg concatArg = InsnArg.wrapArg(concat);
644				concatArg.setType(ArgType.STRING);
645				ArithNode newInsn = ArithNode.oneArgOp(ArithOp.ADD, fArg, concatArg);
646				newInsn.copyAttributesFrom(wrap);
647				newInsn.setOffset(wrap.getOffset());
648				return newInsn;
649			} catch (Exception e) {
650				LOG.debug("Can't convert field arith insn: {}, mth: {}", insn, mth, e);
651			}
652			return null;
653		}
654	}
