238		public static boolean dontGenerateIfNotUsed(InsnNode insn) {
239			RegisterArg resArg = insn.getResult();
240			if (resArg != null) {
241				SSAVar ssaVar = resArg.getSVar();
242				for (RegisterArg arg : ssaVar.getUseList()) {
243					InsnNode parentInsn = arg.getParentInsn();
244					if (parentInsn != null
245							&& !parentInsn.contains(AFlag.DONT_GENERATE)) {
246						return false;
247					}
248				}
249			}
250			insn.add(AFlag.DONT_GENERATE);
251			return true;
252		}
