254		public static <T extends InsnArg> boolean containsVar(List<T> list, RegisterArg arg) {
255			if (list == null || list.isEmpty()) {
256				return false;
257			}
258			for (InsnArg insnArg : list) {
259				if (insnArg == arg || arg.sameRegAndSVar(insnArg)) {
260					return true;
261				}
262			}
263			return false;
264		}
265	
266		public static boolean containsVar(InsnNode insn, RegisterArg arg) {
267			if (insn == null) {
268				return false;
269			}
270			RegisterArg result = insn.getResult();
271			if (result != null && result.sameRegAndSVar(arg)) {
272				return true;
273			}
274			if (insn.getArgsCount() == 0) {
275				return false;
276			}
277			for (InsnArg insnArg : insn.getArguments()) {
278				if (containsVar(insnArg, arg)) {
279					return true;
280				}
281			}
282			return false;
283		}
284	
285		public static boolean containsVar(InsnArg insnArg, RegisterArg arg) {
286			if (insnArg.isRegister()) {
287				return ((RegisterArg) insnArg).sameRegAndSVar(arg);
288			}
289			if (insnArg.isInsnWrap()) {
290				InsnNode wrapInsn = ((InsnWrapArg) insnArg).getWrapInsn();
291				return containsVar(wrapInsn, arg);
292			}
293			return false;
294		}
