123	
124						case NEW_ARRAY:
125							// replace with filled array if 'fill-array' is next instruction
126							NewArrayNode newArrInsn = (NewArrayNode) insn;
127							InsnNode nextInsn = getFirstUseSkipMove(insn.getResult());
128							if (nextInsn != null && nextInsn.getType() == InsnType.FILL_ARRAY) {
129								FillArrayInsn fillArrInsn = (FillArrayInsn) nextInsn;
130								if (checkArrSizes(mth, newArrInsn, fillArrInsn)) {
131									InsnNode filledArr = makeFilledArrayInsn(mth, newArrInsn, fillArrInsn);
132									replaceInsn(mth, block, i, filledArr);
133									remover.addAndUnbind(nextInsn);
134								}
135							}
136							break;
137	
138						case MOVE_EXCEPTION:
139							processMoveException(mth, block, insn, remover);
140							break;
141	
142						case ARITH:
143							processArith(mth, parentClass, (ArithNode) insn);
144							break;
145	
146						case CMP_L:
147						case CMP_G:
148							inlineCMPInsns(mth, block, i, insn, remover);
149							break;
150	
151						case CHECK_CAST:
152							removeCheckCast(mth, block, i, (IndexInsnNode) insn);
153							break;
154	
155						case CAST:
156							fixPrimitiveCast(mth, block, i, insn);
157							break;
158	
159						case IPUT:
160						case IGET:
161							fixFieldUsage(mth, (IndexInsnNode) insn);
162							break;
163	
164						default:
165							break;
166					}
167				}
168				remover.perform();
169			}
170		}
