172		/**
173		 * If field is not visible from use site => cast to origin class
174		 */
175		private static void fixFieldUsage(MethodNode mth, IndexInsnNode insn) {
176			InsnArg instanceArg = insn.getArg(insn.getType() == InsnType.IGET ? 0 : 1);
177			if (instanceArg.contains(AFlag.SUPER)) {
178				return;
179			}
180			if (instanceArg.isInsnWrap() && ((InsnWrapArg) instanceArg).getWrapInsn().getType() == InsnType.CAST) {
181				return;
182			}
183			FieldInfo fieldInfo = (FieldInfo) insn.getIndex();
184			ArgType clsType = fieldInfo.getDeclClass().getType();
185			ArgType instanceType = instanceArg.getType();
186			if (Objects.equals(clsType, instanceType)) {
187				// cast not needed
188				return;
189			}
190	
191			FieldNode fieldNode = mth.root().resolveField(fieldInfo);
192			if (fieldNode == null) {
193				// unknown field
194				TypeCompareEnum result = mth.root().getTypeCompare().compareTypes(instanceType, clsType);
195				if (result.isEqual() || (result == TypeCompareEnum.NARROW_BY_GENERIC && !instanceType.isGenericType())) {
196					return;
197				}
198			} else if (isFieldVisibleInMethod(fieldNode, mth)) {
199				return;
200			}
201			// insert cast
202			IndexInsnNode castInsn = new IndexInsnNode(InsnType.CAST, clsType, 1);
203			castInsn.addArg(instanceArg.duplicate());
204			castInsn.add(AFlag.SYNTHETIC);
205			castInsn.add(AFlag.EXPLICIT_CAST);
206	
207			InsnArg castArg = InsnArg.wrapInsnIntoArg(castInsn);
208			castArg.setType(clsType);
209			insn.replaceArg(instanceArg, castArg);
210			InsnRemover.unbindArgUsage(mth, instanceArg);
211		}
