213		private static boolean isFieldVisibleInMethod(FieldNode field, MethodNode mth) {
214			AccessInfo accessFlags = field.getAccessFlags();
215			if (accessFlags.isPublic()) {
216				return true;
217			}
218			ClassNode useCls = mth.getParentClass();
219			ClassNode fieldCls = field.getParentClass();
220			boolean sameScope = Objects.equals(useCls, fieldCls) && !mth.getAccessFlags().isStatic();
221			if (sameScope) {
222				return true;
223			}
224			if (accessFlags.isPrivate()) {
225				return false;
226			}
227			// package-private or protected
228			if (Objects.equals(useCls.getClassInfo().getPackage(), fieldCls.getClassInfo().getPackage())) {
229				// same package
230				return true;
231			}
232			if (accessFlags.isPackagePrivate()) {
233				return false;
234			}
235			// protected
236			TypeCompareEnum result = mth.root().getTypeCompare().compareTypes(useCls, fieldCls);
237			return result == TypeCompareEnum.NARROW; // true if use class is subclass of field class
238		}
