253			// replace boolean to (byte/char/short/long/double/float) cast with ternary
254			InsnArg castArg = insn.getArg(0);
255			if (castArg.getType() == ArgType.BOOLEAN) {
256				ArgType type = insn.getResult().getType();
257				if (type.isPrimitive()) {
258					TernaryInsn ternary = makeBooleanConvertInsn(insn.getResult(), castArg, type);
259					replaceInsn(mth, block, i, ternary);
260				}
261			}
