264		public static TernaryInsn makeBooleanConvertInsn(RegisterArg result, InsnArg castArg, ArgType type) {
265			InsnArg zero = LiteralArg.make(0, type);
266			long litVal = 1;
267			if (type == ArgType.DOUBLE) {
268				litVal = DOUBLE_TO_BITS;
269			} else if (type == ArgType.FLOAT) {
270				litVal = FLOAT_TO_BITS;
271			}
272			InsnArg one = LiteralArg.make(litVal, type);
273	
274			IfNode ifNode = new IfNode(IfOp.EQ, -1, castArg, LiteralArg.litTrue());
275			IfCondition condition = IfCondition.fromIfNode(ifNode);
276			return new TernaryInsn(condition, result, one, zero);
277		}
