317		 * returns how many lines does it have between start to pos in content.
318		 */
319		public static int countLinesByPos(String content, int pos, int start) {
320			if (start >= pos) {
321				return 0;
322			}
323			int count = 0;
324			int tempPos = start;
325			do {
326				tempPos = content.indexOf("\n", tempPos);
327				if (tempPos == -1) {
328					break;
329				}
330				if (tempPos >= pos) {
331					break;
332				}
333				count += 1;
334				tempPos += 1;
335			} while (tempPos < content.length());
336			return count;
337		}
