339		/**
340		 * returns lines that contain pos to end if end is not -1.
341		 */
342		public static String getLine(String content, int pos, int end) {
343			if (pos >= content.length()) {
344				return "";
345			}
346			if (end != -1) {
347				if (end > content.length()) {
348					end = content.length() - 1;
349				}
350			} else {
351				end = pos + 1;
352			}
353			// get to line head
354			int headPos = content.lastIndexOf("\n", pos);
355			if (headPos == -1) {
356				headPos = 0;
357			}
358			// get to line end
359			int endPos = content.indexOf("\n", end);
360			if (endPos == -1) {
361				endPos = content.length();
362			}
363			return content.substring(headPos, endPos);
364		}
