375		/**
376		 * Inline CMP instructions into 'if' to help conditions merging
377		 */
378		private static void inlineCMPInsns(MethodNode mth, BlockNode block, int i, InsnNode insn, InsnRemover remover) {
379			RegisterArg resArg = insn.getResult();
380			List<RegisterArg> useList = resArg.getSVar().getUseList();
381			if (allMatch(useList, use -> InsnUtils.isInsnType(use.getParentInsn(), InsnType.IF))) {
382				for (RegisterArg useArg : new ArrayList<>(useList)) {
383					InsnNode useInsn = useArg.getParentInsn();
384					if (useInsn != null) {
385						InsnArg wrapArg = InsnArg.wrapInsnIntoArg(insn.copyWithoutResult());
386						if (!useInsn.replaceArg(useArg, wrapArg)) {
387							mth.addWarnComment("Failed to inline CMP insn: " + insn + " into " + useInsn);
388							return;
389						}
390					}
391				}
392				remover.addAndUnbind(insn);
393			}
394		}
