396		private static boolean checkArrSizes(MethodNode mth, NewArrayNode newArrInsn, FillArrayInsn fillArrInsn) {
397			int dataSize = fillArrInsn.getSize();
398			InsnArg arrSizeArg = newArrInsn.getArg(0);
399			Object value = InsnUtils.getConstValueByArg(mth.root(), arrSizeArg);
400			if (value instanceof LiteralArg) {
401				long literal = ((LiteralArg) value).getLiteral();
402				return dataSize == (int) literal;
403			}
404			return false;
405		}
