407		private static void removeCheckCast(MethodNode mth, BlockNode block, int i, IndexInsnNode insn) {
408			InsnArg castArg = insn.getArg(0);
409			if (castArg.isZeroLiteral()) {
410				// always keep cast for 'null'
411				insn.add(AFlag.EXPLICIT_CAST);
412				return;
413			}
414			ArgType castType = (ArgType) insn.getIndex();
415			if (!ArgType.isCastNeeded(mth.root(), castArg.getType(), castType)) {
416				RegisterArg result = insn.getResult();
417				result.setType(castArg.getType());
418	
419				InsnNode move = new InsnNode(InsnType.MOVE, 1);
420				move.setResult(result);
421				move.addArg(castArg);
422				replaceInsn(mth, block, i, move);
423				return;
424			}
425			InsnNode prevCast = isCastDuplicate(insn);
426			if (prevCast != null) {
427				// replace previous cast with move
428				InsnNode move = new InsnNode(InsnType.MOVE, 1);
429				move.setResult(prevCast.getResult());
430				move.addArg(prevCast.getArg(0));
431				replaceInsn(mth, block, prevCast, move);
432			}
433		}
434	
435		private static @Nullable InsnNode isCastDuplicate(IndexInsnNode castInsn) {
436			InsnArg arg = castInsn.getArg(0);
437			if (arg.isRegister()) {
438				SSAVar sVar = ((RegisterArg) arg).getSVar();
439				if (sVar != null && sVar.getUseCount() == 1 && !sVar.isUsedInPhi()) {
440					InsnNode assignInsn = sVar.getAssign().getParentInsn();
441					if (assignInsn != null && assignInsn.getType() == InsnType.CHECK_CAST) {
442						ArgType assignCastType = (ArgType) ((IndexInsnNode) assignInsn).getIndex();
443						if (assignCastType.equals(castInsn.getIndex())) {
444							return assignInsn;
445						}
446					}
447				}
448			}
449			return null;
450		}
