455		private static void removeStep(MethodNode mth, InsnRemover remover) {
456			for (BlockNode block : mth.getBasicBlocks()) {
457				remover.setBlock(block);
458				for (InsnNode insn : block.getInstructions()) {
459					switch (insn.getType()) {
460						case NOP:
461						case GOTO:
462						case NEW_INSTANCE:
463							remover.addAndUnbind(insn);
464							break;
465	
466						default:
467							if (insn.contains(AFlag.REMOVE)) {
468								remover.addAndUnbind(insn);
469							}
470							break;
471					}
472				}
473				remover.perform();
474			}
475		}
