477		private static void iterativeRemoveStep(MethodNode mth) {
478			boolean changed;
479			do {
480				changed = false;
481				for (BlockNode block : mth.getBasicBlocks()) {
482					for (InsnNode insn : block.getInstructions()) {
483						if (insn.getType() == InsnType.MOVE
484								&& insn.isAttrStorageEmpty()
485								&& isResultArgNotUsed(insn)) {
486							InsnRemover.remove(mth, block, insn);
487							changed = true;
488							break;
489						}
490					}
491				}
492			} while (changed);
493		}
