495		private static boolean isResultArgNotUsed(InsnNode insn) {
496			RegisterArg result = insn.getResult();
497			if (result != null) {
498				SSAVar ssaVar = result.getSVar();
499				return ssaVar.getUseCount() == 0;

500			}
501			return false;
502		}
