504		/**
505		 * For args in anonymous constructor invoke apply:
506		 * - forbid inline into constructor call
507		 * - make variables final (compiler require this implicitly)
508		 */
509		private static void processAnonymousConstructor(MethodNode mth, ConstructorInsn co) {
510			IMethodDetails callMthDetails = mth.root().getMethodUtils().getMethodDetails(co);
511			if (!(callMthDetails instanceof MethodNode)) {
512				return;
513			}
514			MethodNode callMth = (MethodNode) callMthDetails;
515			if (!callMth.contains(AFlag.ANONYMOUS_CONSTRUCTOR) || callMth.contains(AFlag.NO_SKIP_ARGS)) {
516				return;
517			}
518			SkipMethodArgsAttr attr = callMth.get(AType.SKIP_MTH_ARGS);
519			if (attr != null) {
520				int argsCount = Math.min(callMth.getMethodInfo().getArgsCount(), co.getArgsCount());
521				for (int i = 0; i < argsCount; i++) {
522					if (attr.isSkip(i)) {
523						anonymousCallArgMod(co.getArg(i));
524					}
525				}
526			} else {
527				// additional info not available apply mods to all args (the safest solution)
528				co.getArguments().forEach(ModVisitor::anonymousCallArgMod);
529			}
530		}
