532		private static void anonymousCallArgMod(InsnArg arg) {
533			arg.add(AFlag.DONT_INLINE);
534			if (arg.isRegister()) {
535				((RegisterArg) arg).getSVar().getCodeVar().setFinal(true);
536			}
537		}
