539		/**
540		 * Return first usage instruction for arg.
541		 * If used only once try to follow move chain
542		 */
543		@Nullable
544		private static InsnNode getFirstUseSkipMove(RegisterArg arg) {
545			SSAVar sVar = arg.getSVar();
546			int useCount = sVar.getUseCount();
547			if (useCount == 0) {
548				return null;
549			}
550			RegisterArg useArg = sVar.getUseList().get(0);
551			InsnNode parentInsn = useArg.getParentInsn();
552			if (parentInsn == null) {
553				return null;
554			}
555			if (useCount == 1 && parentInsn.getType() == InsnType.MOVE) {
556				return getFirstUseSkipMove(parentInsn.getResult());
557			}
558			return parentInsn;
559		}
