561		private static InsnNode makeFilledArrayInsn(MethodNode mth, NewArrayNode newArrayNode, FillArrayInsn insn) {
562			ArgType insnArrayType = newArrayNode.getArrayType();
563			ArgType insnElementType = insnArrayType.getArrayElement();
564			ArgType elType = insn.getElementType();
565			if (!elType.isTypeKnown()
566					&& insnElementType.isPrimitive()
567					&& elType.contains(insnElementType.getPrimitiveType())) {
568				elType = insnElementType;
569			}
570			if (!elType.equals(insnElementType) && !insnArrayType.equals(ArgType.OBJECT)) {
571				mth.addWarn("Incorrect type for fill-array insn " + InsnUtils.formatOffset(insn.getOffset())
572						+ ", element type: " + elType + ", insn element type: " + insnElementType);
573			}
574			if (!elType.isTypeKnown()) {
575				LOG.warn("Unknown array element type: {} in mth: {}", elType, mth);
576				elType = insnElementType.isTypeKnown() ? insnElementType : elType.selectFirst();
577				if (elType == null) {
578					throw new JadxRuntimeException("Null array element type");
579				}
580			}
581	
582			List<LiteralArg> list = insn.getLiteralArgs(elType);
583			InsnNode filledArr = new FilledNewArrayNode(elType, list.size());
584			filledArr.setResult(newArrayNode.getResult().duplicate());
585			for (LiteralArg arg : list) {
586				IFieldInfoRef f = mth.getParentClass().getConstFieldByLiteralArg(arg);
587				if (f != null) {
588					InsnNode fGet = new IndexInsnNode(InsnType.SGET, f.getFieldInfo(), 0);
589					filledArr.addArg(InsnArg.wrapArg(fGet));
590					addFieldUsage(f, mth);
591				} else {
592					filledArr.addArg(arg.duplicate());
593				}
594			}
595			return filledArr;
596		}
