598		private static void processMoveException(MethodNode mth, BlockNode block, InsnNode insn, InsnRemover remover) {
599			ExcHandlerAttr excHandlerAttr = block.get(AType.EXC_HANDLER);
600			if (excHandlerAttr == null) {
601				return;
602			}
603			ExceptionHandler excHandler = excHandlerAttr.getHandler();
604	
605			// result arg used both in this insn and exception handler,
606			RegisterArg resArg = insn.getResult();
607			ArgType type = excHandler.getArgType();
608			String name = excHandler.isCatchAll() ? "th" : "e";
609			if (resArg.getName() == null) {
610				resArg.setName(name);
611			}
612			SSAVar sVar = insn.getResult().getSVar();
613			if (sVar.getUseCount() == 0) {
614				excHandler.setArg(new NamedArg(name, type));
615				remover.addAndUnbind(insn);
616			} else if (sVar.isUsedInPhi()) {
617				// exception var moved to external variable => replace with 'move' insn
618				InsnNode moveInsn = new InsnNode(InsnType.MOVE, 1);
619				moveInsn.setResult(insn.getResult());
620				NamedArg namedArg = new NamedArg(name, type);
621				moveInsn.addArg(namedArg);
622				excHandler.setArg(namedArg);
623				replaceInsn(mth, block, 0, moveInsn);
624			}
625			block.copyAttributeFrom(insn, AType.CODE_COMMENTS); // save comment
626		}
