38	@JadxVisitor(
39			name = "ExtractFieldInit",
40			desc = "Move duplicated field initialization from constructors",
41			runAfter = ModVisitor.class,
42			runBefore = ClassModifier.class
43	)
44	public class ExtractFieldInit extends AbstractVisitor {
45	
46		@Override
47		public boolean visit(ClassNode cls) throws JadxException {
48			for (ClassNode inner : cls.getInnerClasses()) {
49				visit(inner);
50			}
51			if (!cls.getFields().isEmpty()) {
52				moveStaticFieldsInit(cls);
53				moveCommonFieldsInit(cls);
54			}
55			return false;
56		}
