70		private static final class ConstructorInitInfo {
71			final MethodNode constructorMth;
72			final List<FieldInitInfo> fieldInits;
73	
74			private ConstructorInitInfo(MethodNode constructorMth, List<FieldInitInfo> fieldInits) {
75				this.constructorMth = constructorMth;
76				this.fieldInits = fieldInits;
