80		private static void moveStaticFieldsInit(ClassNode cls) {

80		private static void moveStaticFieldsInit(ClassNode cls) {
81			MethodNode classInitMth = cls.getClassInitMth();
82			if (classInitMth == null
83					|| !classInitMth.getAccessFlags().isStatic()
84					|| classInitMth.isNoCode()
85					|| classInitMth.getBasicBlocks() == null) {
86				return;
87			}
88			if (ListUtils.noneMatch(cls.getFields(), FieldNode::isStatic)) {
89				return;
90			}
91			while (processStaticFields(cls, classInitMth)) {
92				// sometimes instructions moved to field init prevent from vars inline -> inline and try again
93				CodeShrinkVisitor.shrinkMethod(classInitMth);
94			}
95		}
