97		private static boolean processStaticFields(ClassNode cls, MethodNode classInitMth) {
98			List<FieldInitInfo> inits = collectFieldsInit(cls, classInitMth, InsnType.SPUT);
99			if (inits.isEmpty()) {
100				return false;
101			}
102			// ignore field init constant if field initialized in class init method
103			for (FieldInitInfo fieldInit : inits) {
104				FieldNode field = fieldInit.fieldNode;
105				if (field.getAccessFlags().isFinal()) {
106					field.remove(JadxAttrType.CONSTANT_VALUE);
107				}
108			}
109			filterFieldsInit(inits);
110			if (inits.isEmpty()) {
111				return false;
112			}
113			for (FieldInitInfo fieldInit : inits) {
114				IndexInsnNode insn = fieldInit.putInsn;
115				InsnArg arg = insn.getArg(0);
116				if (arg instanceof InsnWrapArg) {
117					((InsnWrapArg) arg).getWrapInsn().add(AFlag.DECLARE_VAR);
118				}
119				InsnRemover.remove(classInitMth, insn);
120				addFieldInitAttr(classInitMth, fieldInit.fieldNode, insn);
121			}
122			fixFieldsOrder(cls, inits);
123			return true;
124		}
