126		private static void moveCommonFieldsInit(ClassNode cls) {
127			if (ListUtils.noneMatch(cls.getFields(), FieldNode::isInstance)) {
128				return;
129			}
130			List<MethodNode> constructors = getConstructorsList(cls);
131			if (constructors.isEmpty()) {
132				return;
133			}
134			List<ConstructorInitInfo> infoList = new ArrayList<>(constructors.size());
135			for (MethodNode constructorMth : constructors) {
136				List<FieldInitInfo> inits = collectFieldsInit(cls, constructorMth, InsnType.IPUT);
137				filterFieldsInit(inits);
138				if (inits.isEmpty()) {
139					return;
140				}
141				infoList.add(new ConstructorInitInfo(constructorMth, inits));
142			}
143			// compare collected instructions
144			ConstructorInitInfo common = null;
145			for (ConstructorInitInfo info : infoList) {
146				if (common == null) {
147					common = info;
148					continue;
149				}
150				if (!compareFieldInits(common.fieldInits, info.fieldInits)) {
151					return;
152				}
153			}
154			if (common == null) {
155				return;
156			}
157			// all checks passed
158			for (ConstructorInitInfo info : infoList) {
159				for (FieldInitInfo fieldInit : info.fieldInits) {
160					IndexInsnNode putInsn = fieldInit.putInsn;
161					InsnArg arg = putInsn.getArg(0);
162					if (arg instanceof InsnWrapArg) {
163						((InsnWrapArg) arg).getWrapInsn().add(AFlag.DECLARE_VAR);
164					}
165					InsnRemover.remove(info.constructorMth, putInsn);
166				}
167			}
168			for (FieldInitInfo fieldInit : common.fieldInits) {
169				addFieldInitAttr(common.constructorMth, fieldInit.fieldNode, fieldInit.putInsn);
170			}
171			fixFieldsOrder(cls, common.fieldInits);
172		}
