174		private static List<FieldInitInfo> collectFieldsInit(ClassNode cls, MethodNode mth, InsnType putType) {
175			List<FieldInitInfo> fieldsInit = new ArrayList<>();
176			Set<BlockNode> singlePathBlocks = new HashSet<>();
177			BlockUtils.visitSinglePath(mth.getEnterBlock(), singlePathBlocks::add);
178	
179			boolean canReorder = true;
180			for (BlockNode block : mth.getBasicBlocks()) {
181				for (InsnNode insn : block.getInstructions()) {
182					boolean fieldInsn = false;
183					if (insn.getType() == putType) {
184						IndexInsnNode putInsn = (IndexInsnNode) insn;
185						FieldInfo field = (FieldInfo) putInsn.getIndex();
186						if (field.getDeclClass().equals(cls.getClassInfo())) {
187							FieldNode fn = cls.searchField(field);
188							if (fn != null) {
189								boolean canMove = canReorder && singlePathBlocks.contains(block);
190								fieldsInit.add(new FieldInitInfo(fn, putInsn, canMove));
191								fieldInsn = true;
192							}
193						}
194					}
195					if (!fieldInsn && canReorder && !insn.canReorder()) {
196						canReorder = false;
197					}
198				}
199			}
200			return fieldsInit;
201		}
202	
203		private static void filterFieldsInit(List<FieldInitInfo> inits) {
204			// exclude fields initialized several times
205			Set<FieldInfo> excludedFields = inits
206					.stream()
207					.collect(Collectors.toMap(fi -> fi.fieldNode, fi -> 1, Integer::sum))
208					.entrySet()
209					.stream()
210					.filter(v -> v.getValue() > 1)
211					.map(v -> v.getKey().getFieldInfo())
212					.collect(Collectors.toSet());
213	
214			for (FieldInitInfo initInfo : inits) {
215				if (!checkInsn(initInfo)) {
216					excludedFields.add(initInfo.fieldNode.getFieldInfo());
217				}
218			}
219			if (!excludedFields.isEmpty()) {
220				boolean changed;
221				do {
222					changed = false;
223					for (FieldInitInfo initInfo : inits) {
224						FieldInfo fieldInfo = initInfo.fieldNode.getFieldInfo();
225						if (excludedFields.contains(fieldInfo)) {
226							continue;
227						}
228						if (insnUseExcludedField(initInfo, excludedFields)) {
229							excludedFields.add(fieldInfo);
230							changed = true;
231						}
232					}
233				} while (changed);
234			}
235	
236			// apply
237			if (!excludedFields.isEmpty()) {
238				inits.removeIf(fi -> excludedFields.contains(fi.fieldNode.getFieldInfo()));
239			}
240		}
241	
242		private static boolean checkInsn(FieldInitInfo initInfo) {
243			if (!initInfo.canMove) {
244				return false;
245			}
246			IndexInsnNode insn = initInfo.putInsn;
247			InsnArg arg = insn.getArg(0);
248			if (arg.isInsnWrap()) {
249				InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
250				if (!wrapInsn.canReorder() && insn.contains(AType.EXC_CATCH)) {
251					return false;
252				}
253			} else {
254				return arg.isLiteral() || arg.isThis();
255			}
256			Set<RegisterArg> regs = new HashSet<>();
257			insn.getRegisterArgs(regs);
258			if (!regs.isEmpty()) {
259				for (RegisterArg reg : regs) {
260					if (!reg.isThis()) {
261						return false;
262					}
263				}
264			}
265			return true;
266		}
267	
268		private static boolean insnUseExcludedField(FieldInitInfo initInfo, Set<FieldInfo> excludedFields) {
269			if (excludedFields.isEmpty()) {
270				return false;
271			}
272			IndexInsnNode insn = initInfo.putInsn;
273			boolean staticField = insn.getType() == InsnType.SPUT;
274			InsnType useType = staticField ? InsnType.SGET : InsnType.IGET;
275			// exclude if init code use any excluded field
276			Boolean exclude = insn.visitInsns(innerInsn -> {
277				if (innerInsn.getType() == useType) {
278					FieldInfo fieldInfo = (FieldInfo) ((IndexInsnNode) innerInsn).getIndex();
279					if (excludedFields.contains(fieldInfo)) {

280						return true;
281					}
282				}
283				return null;
284			});
285			return Objects.equals(exclude, Boolean.TRUE);
286		}
