288		private static void fixFieldsOrder(ClassNode cls, List<FieldInitInfo> inits) {
289			List<FieldNode> orderedFields = processFieldsDependencies(cls, inits);
290	
291			// apply source line and alias name sorting (same as for methods and inner classes)
292			List<FieldNode> clsFields = cls.getFields();
293			Map<FieldNode, String> sortingMap = new HashMap<>();
294			clsFields.sort(Comparator.comparingInt(FieldNode::getSourceLine)
295					.thenComparing(f -> sortingMap.computeIfAbsent(f, ClassGen::getShortAlias)));
296	
297			if (!orderedFields.isEmpty()) {
298				// check if already ordered
299				boolean ordered = Collections.indexOfSubList(clsFields, orderedFields) != -1;
300				if (!ordered) {
301					clsFields.removeAll(orderedFields);
302					clsFields.addAll(orderedFields);
303				}
304			}
305		}
306	
307		private static List<FieldNode> processFieldsDependencies(ClassNode cls, List<FieldInitInfo> inits) {
308			// collect dependant fields
309			Map<FieldNode, List<FieldNode>> deps = buildFieldDeps(cls, inits);
310			if (deps.isEmpty()) {
311				return Collections.emptyList();
312			}
313			// build new list with deps fields before usage field
314			List<FieldNode> orderedFields = Utils.collectionMap(inits, v -> v.fieldNode);
315			List<FieldNode> result = new ArrayList<>();
316			for (FieldNode field : orderedFields) {
317				int idx = result.indexOf(field);
318				List<FieldNode> fieldDeps = deps.get(field);
319				if (fieldDeps == null) {
320					if (idx == -1) {
321						result.add(field);
322					}
323					continue;
324				}
325				if (idx == -1) {
326					for (FieldNode depField : fieldDeps) {
327						if (!result.contains(depField)) {
328							result.add(depField);
329						}
330					}
331					result.add(field);
332					continue;
333				}
334				for (FieldNode depField : fieldDeps) {
335					int depIdx = result.indexOf(depField);
336					if (depIdx == -1) {
337						result.add(idx, depField);
338					} else if (depIdx > idx) {
339						result.remove(depIdx);
340						result.add(idx, depField);
341					}
342				}
343			}
344			return result;
345		}
346	
347		private static Map<FieldNode, List<FieldNode>> buildFieldDeps(ClassNode cls, List<FieldInitInfo> inits) {
348			Map<FieldNode, List<FieldNode>> deps = new HashMap<>(inits.size());
349			for (FieldInitInfo initInfo : inits) {
350				IndexInsnNode insn = initInfo.putInsn;
351				boolean staticField = insn.getType() == InsnType.SPUT;
352				InsnType useType = staticField ? InsnType.SGET : InsnType.IGET;
353				insn.visitInsns(subInsn -> {
354					if (subInsn.getType() == useType) {
355						FieldInfo fieldInfo = (FieldInfo) ((IndexInsnNode) subInsn).getIndex();
356						if (fieldInfo.getDeclClass().equals(cls.getClassInfo())) {
357							FieldNode depField = cls.searchField(fieldInfo);
358							if (depField != null) {
359								deps.computeIfAbsent(initInfo.fieldNode, k -> new ArrayList<>())
360										.add(depField);
361							}
362						}
363					}
364				});
365			}
366			return deps;
367		}
368	
369		private static boolean compareFieldInits(List<FieldInitInfo> base, List<FieldInitInfo> other) {
370			if (base.size() != other.size()) {
371				return false;
372			}
373			int count = base.size();
374			for (int i = 0; i < count; i++) {
375				InsnNode baseInsn = base.get(i).putInsn;
376				InsnNode otherInsn = other.get(i).putInsn;
377				if (!sameFieldInit(baseInsn, otherInsn)) {
378					return false;
379				}
380			}
381			return true;
382		}
383	
384		private static boolean sameFieldInit(InsnNode first, InsnNode second) {
385			if (!first.isSame(second)) {
386				return false;
387			}
388			for (int i = 0; i < first.getArgsCount(); i++) {
389				InsnArg firstArg = first.getArg(i);
390				InsnArg secondArg = second.getArg(i);
391				// Constructors can use different registers and SSA variables for the same instance.
392				if (firstArg.isThis() && secondArg.isThis()) {
393					continue;
394				}
395				if (firstArg.isInsnWrap() && secondArg.isInsnWrap()) {
396					if (!sameFieldInit(((InsnWrapArg) firstArg).getWrapInsn(), ((InsnWrapArg) secondArg).getWrapInsn())) {
397						return false;
398					}
399				} else if (!firstArg.equals(secondArg)) {
400					return false;
401				}
402			}
403			return true;
404		}
