406		private static List<MethodNode> getConstructorsList(ClassNode cls) {
407			List<MethodNode> list = new ArrayList<>();
408			for (MethodNode mth : cls.getMethods()) {
409				AccessInfo accFlags = mth.getAccessFlags();

406		private static List<MethodNode> getConstructorsList(ClassNode cls) {
407			List<MethodNode> list = new ArrayList<>();
408			for (MethodNode mth : cls.getMethods()) {
409				AccessInfo accFlags = mth.getAccessFlags();
410				if (!accFlags.isStatic() && accFlags.isConstructor()) {
411					list.add(mth);
412					if (mth.isNoCode() || BlockUtils.isAllBlocksEmpty(mth.getBasicBlocks())) {
413						return Collections.emptyList();
414					}
415				}
416			}
417			return list;
418		}
