420		private static void addFieldInitAttr(MethodNode mth, FieldNode field, IndexInsnNode putInsn) {
421			InsnNode assignInsn;
422			InsnArg fldArg = putInsn.getArg(0);
423			if (fldArg.isInsnWrap()) {
424				assignInsn = ((InsnWrapArg) fldArg).getWrapInsn();
425			} else {
426				assignInsn = InsnNode.wrapArg(fldArg);
427			}
